tools.example:
x = linspace(0, 2*pi, 100);
plot(x, sin(x), '-b', 'LineWidth', 1.5, 'DisplayName', 'sin')
hold on
plot(x, cos(x), '--r', 'DisplayName', 'cos')
hold off
legend
h = plot(x, sin(x));
h.Color = [0.2 0.6 0.2];

rng(0);
x = randn(200,1); y = 2*x + randn(200,1);
scatter(x, y, 30, abs(x), 'filled', 'MarkerFaceAlpha', 0.5)
colorbar
xlabel('x'); ylabel('y')

rng(0);
n = 300;
x = randn(n,1); y = randn(n,1); z = x.^2 + y.^2;
scatter3(x, y, z, 25, z, 'filled')
colorbar
view(-30, 20)
grid on

cats = categorical(["alpha" "beta" "gamma"]);
vals = [4 7 3];
b = bar(cats, vals, 'FaceColor', 'flat');
b.CData(2, :) = [0.85 0.33 0.1];
ytips = vals + 0.2;
text(1:3, ytips, string(vals), 'HorizontalAlignment', 'center')
bar(magic(4), 'stacked')

names = categorical(["very long label A"; "label B"; "label C"]);
vals = [12; 30; 7];
[~, ord] = sort(vals);
barh(reordercats(names(ord), string(names(ord))), vals(ord))
xlabel('count')

rng(0);
a = randn(1000,1);
b = 1 + 0.5*randn(1000,1);
histogram(a, 'Normalization', 'pdf', 'FaceAlpha', 0.5)
hold on
histogram(b, 'Normalization', 'pdf', 'FaceAlpha', 0.5)
hold off
legend('a', 'b')
h = histogram(a);
h.BinWidth = 0.25;

rng(0);
x = randn(5000,1);
y = x + 0.5*randn(5000,1);
histogram2(x, y, [40 40], 'DisplayStyle', 'tile', 'ShowEmptyBins', 'on')
colorbar
axis equal

vals = [30 25 20 15 10];
labels = {'A','B','C','D','E'};
pie(vals, [0 1 0 0 0], labels)
title('Share by category')
legend(labels, 'Location', 'eastoutside')

x = 1:10;
Y = [rand(10,1) rand(10,1)*2 rand(10,1)*0.5];
area(x, Y, 'FaceAlpha', 0.7)
legend('cpu','memory','io', 'Location', 'northwest')
ylabel('usage')

t = 0:10;
u = [0 0 1 1 1 0 0 2 2 0 0];
stairs(t, u, 'LineWidth', 1.5)
ylim([-0.5 2.5])
[xb, yb] = stairs(t, u);
numel(xb)

n = 0:20;
h = 0.8.^n;
stem(n, h, 'filled', 'MarkerSize', 4)
xlabel('n'); ylabel('h[n]')
title('Impulse response')
stem3(rand(1,10), rand(1,10), rand(1,10), 'filled')

x = 1:5;
y = [2 4 3 5 4];
sd = [0.3 0.5 0.2 0.6 0.4];
errorbar(x, y, sd, '-o', 'CapSize', 10, 'LineWidth', 1.2)
xlim([0.5 5.5])
errorbar(x, y, sd, sd, 0.1*ones(size(x)), 0.1*ones(size(x)), 'o')

rng(0);
g = categorical(repelem(["a";"b";"c"], 50));
y = [randn(50,1); 1+randn(50,1); 0.5*randn(50,1)];
boxchart(g, y)
ylabel('response')
boxchart(g, y, 'Notch', 'on')

rng(0);
g = categorical(repelem(["a";"b"], 40));
y = [randn(40,1); 1.5+randn(40,1)];
boxchart(g, y, 'BoxFaceColor', [0.7 0.7 0.7])
hold on
swarmchart(g, y, 20, 'filled', 'MarkerFaceAlpha', 0.6)
hold off

rng(0);
C = round(10*rand(4));
h = heatmap({'a','b','c','d'}, {'w','x','y','z'}, C);
h.Title = 'Counts';
h.Colormap = parula;
h.CellLabelFormat = '%.0f';

theta = linspace(0, 2*pi, 400);
rho = abs(cos(2*theta));
polarplot(theta, rho, 'LineWidth', 1.5)
pax = gca;
pax.ThetaZeroLocation = 'top';
pax.ThetaDir = 'clockwise';
rlim([0 1])

n = 2.^(2:12);
err = 1 ./ n.^2;
loglog(n, err, '-o', 'LineWidth', 1.2)
grid on
xlabel('n'); ylabel('error')
p = polyfit(log10(n), log10(err), 1);
title(sprintf('slope = %.2f', p(1)))

w = logspace(-1, 3, 400);
mag = 20*log10(1 ./ sqrt(1 + (w/10).^2));
semilogx(w, mag, 'LineWidth', 1.2)
grid on
xlabel('\omega (rad/s)'); ylabel('|H| (dB)')

A = gallery('poisson', 20);
b = ones(size(A,1), 1);
[~, ~, ~, ~, resvec] = pcg(A, b, 1e-12, 200);
semilogy(0:numel(resvec)-1, resvec, '-o')
grid on
xlabel('iteration'); ylabel('residual norm')

[X, Y] = meshgrid(linspace(-3, 3, 100));
Z = peaks(X, Y);
[M, c] = contour(X, Y, Z, 15, 'ShowText', 'on');
c.LineWidth = 1;
colorbar
contour(X, Y, Z, [0 0], 'k', 'LineWidth', 2)

[X, Y] = meshgrid(linspace(-3, 3, 120));
Z = peaks(X, Y);
contourf(X, Y, Z, 20, 'LineColor', 'none')
colormap(parula)
colorbar
axis equal tight

[X, Y] = meshgrid(linspace(-3, 3, 60));
Z = peaks(X, Y);
s = surf(X, Y, Z);
s.EdgeColor = 'none';
colormap(turbo)
colorbar
lighting gouraud
camlight
view(-40, 30)

[X, Y] = meshgrid(linspace(-2, 2, 40));
Z = X .* exp(-X.^2 - Y.^2);
mesh(X, Y, Z)
colorbar
hidden off
meshc(X, Y, Z)

[X, Y] = meshgrid(linspace(-3, 3, 60));
Z = peaks(X, Y);
surfc(X, Y, Z, 'EdgeColor', 'none')
colormap(parula)
colorbar
view(-35, 40)

[X, Y] = meshgrid(1:4, 1:3);
size(X)
X
Y
Z = X.^2 + Y.^2;
surf(X, Y, Z)

[X, Y] = ndgrid(1:4, 1:3);
size(X)
[Xm, Ym] = meshgrid(1:3, 1:4);
isequal(X, Xm')
[A, B, C] = ndgrid(1:2, 1:3, 1:4);
size(A)

RGB = uint8(255 * rand(50, 80, 3));
image(RGB)
axis image off
ind = randi(64, 50, 80);
image(ind)
colormap(parula(64))

[X, Y] = meshgrid(linspace(-3, 3, 60));
Z = peaks(X, Y);
pcolor(X, Y, Z)
shading interp
colorbar
axis equal tight

[X, Y] = meshgrid(-2:0.25:2);
Z = X .* exp(-X.^2 - Y.^2);
[U, V] = gradient(Z, 0.25);
contour(X, Y, Z, 15)
hold on
quiver(X, Y, U, V, 1.2, 'k')
hold off
axis equal

[X, Y] = meshgrid(-2:0.5:2);
Z = X.^2 - Y.^2;
[U, V] = gradient(Z, 0.5);
W = zeros(size(U));
surf(X, Y, Z, 'FaceAlpha', 0.6, 'EdgeColor', 'none')
hold on
quiver3(X, Y, Z, U, V, W, 'k')
hold off
view(-40, 30)

[X, Y] = meshgrid(-3:0.2:3);
U = -Y; V = X;
[sx, sy] = meshgrid(-3:1:3, 0);
h = streamline(X, Y, U, V, sx, sy);
set(h, 'Color', [0.2 0.4 0.8])
axis equal
hold on; quiver(X, Y, U, V, 'Color', [0.8 0.8 0.8]); hold off

x = linspace(0, 10, 100);
y = sin(x);
sd = 0.2 * ones(size(x));
fill([x fliplr(x)], [y+sd fliplr(y-sd)], [0.8 0.85 1], 'EdgeColor', 'none')
hold on
plot(x, y, 'b', 'LineWidth', 1.5)
hold off

V = [0 0; 1 0; 1 1; 0 1];
F = [1 2 3; 1 3 4];
p = patch('Faces', F, 'Vertices', V, 'FaceVertexCData', [0.2; 0.8], ...
          'FaceColor', 'flat', 'EdgeColor', 'k');
colorbar
axis equal
[fv] = isosurface(rand(20,20,20), 0.5);
patch(fv, 'FaceColor', 'red', 'EdgeColor', 'none');

plot(1:10, rand(1,10))
line([1 10], [0.5 0.5], 'Color', 'r', 'LineStyle', '--')
yline(0.8, ':k', 'threshold')
xline(5, '-g')
h = line('XData', [], 'YData', []);
h.XData = 1:5; h.YData = rand(1,5);
